-- Demo data for the admin database (staging only). Generated by deploy/demo/build.py: edit the
-- text files there and rebuild instead of editing this file.
-- Demo rows are marked by the author email demo@openuvoice.com; when a demo announcement exists, the
-- data is already here and nothing runs.
\set ON_ERROR_STOP on
select exists (select 1 from announcements where author_email = 'demo@openuvoice.com') as seeded \gset
\if :seeded
\echo Admin demo data already present, nothing to do.
\quit
\endif

begin;

insert into inquiries (course_number, type, status, content, handled_by, internal_note, created_at, updated_at)
select v.course, v.type, v.status, v.content, v.handled_by, v.note,
       now() - v.days * interval '1 day',
       now() - v.days * interval '1 day' + case when v.status = 'new' then interval '0' else interval '2 days' end
  from (values
    (20215, 'exams', 'new', 1, null, null, 'במועד א'' של מכניקה השנה היו שלוש שאלות על גוף קשיח מתוך חמש, נושא שקיבל רק שני ממ״נים. הרגשנו שהמבחן לא מייצג את החומר. אפשר להעלות את זה מול צוות הקורס?'),
    (20250, 'staff', 'new', 2, null, null, 'המנחה בקבוצה שלנו ביטל שלושה מפגשים ברצף בלי הודעה מראש ובלי הקלטה חלופית. אנחנו כבר שבוע לפני ממ״ן 14 ואין למי לפנות.'),
    (20113, 'accessibility', 'new', 3, null, null, 'אני סטודנט עם לקות למידה ומאושרת לי הארכת זמן, אבל במבחן המקוון האחרון הטופס לא נתן את הזמן הנוסף. מה עושים כדי שזה לא יקרה שוב?'),
    (20432, 'admin', 'new', 4, null, null, 'מפגשי המעבדה ברמת אביב נקבעים בימי שלישי בבוקר. רוב הסטודנטים בקורס עובדים. אפשר לבקש קבוצה נוספת בערב?'),
    (0, 'other', 'new', 5, null, null, 'מציע שהוועד יארגן ערב היכרות לסטודנטים חדשים לפיזיקה, אפילו בזום. בשנה הראשונה הרגשתי לבד לגמרי.'),
    (20320, 'exams', 'in_progress', 9, 'demo@openuvoice.com', 'הועבר לרכזת הקורס, ממתינים לתשובה עד סוף השבוע.', 'במבחן לדוגמה שפורסם באתר יש טעות בפתרון של שאלה 3 (סימן בקומוטטור). כמה סטודנטים כבר שאלו על זה בפורום.'),
    (20409, 'admin', 'in_progress', 12, 'demo@openuvoice.com', 'דיברתי עם מרכז המעבדות, בודקים אפשרות לימי השלמה.', 'בגלל מילואים פספסתי שלושה מפגשי מעבדה. האם יש ימי השלמה לפני סוף הסמסטר?'),
    (20125, 'staff', 'in_progress', 14, 'demo@openuvoice.com', 'נקבעה פגישה עם ראש התוכנית בשבוע הבא.', 'העומס בקורס בסמסטר הקיץ הוא בלתי אפשרי. אולי כדאי לשקול לא להציע את 20125 בקיץ, או לפחות להזהיר יותר במפורש בהרשמה.'),
    (20602, 'accessibility', 'in_progress', 18, 'demo@openuvoice.com', 'ביקשנו מהספרייה גרסה נגישה של הפרקים.', 'הפרקים מהספר נשלחים כסריקות לא נגישות, וקורא המסך שלי לא מצליח לקרוא אותם. האם אפשר לקבל קובץ טקסט?'),
    (20916, 'other', 'in_progress', 20, 'demo@openuvoice.com', 'לבדוק מול צוות המעבדה מה הסטטוס של הציוד.', 'ניסוי העל־מוליכות היה מושבת חצי סמסטר בגלל תקלה במערכת הקירור. האם יש תוכנית לתקן לפני הסמסטר הבא?'),
    (20213, 'exams', 'closed', 35, 'demo@openuvoice.com', 'הצוות פרסם הבהרה, הנושא נסגר.', 'לא ברור אם יחידה 11 (חלקיקים יסודיים) נכללת בחומר למבחן. בפורום יש תשובות סותרות.'),
    (20201, 'staff', 'closed', 41, 'demo@openuvoice.com', 'המנחה חזרה לענות, וקיבלנו התנצלות.', 'המנחה לא עונה על מיילים כבר שלושה שבועות.'),
    (91463, 'admin', 'closed', 50, 'demo@openuvoice.com', 'עודכן באתר, הקישור תקין.', 'הקישור להרצאות המצולמות של יחידה 5 לא עובד כבר שבוע.'),
    (20120, 'other', 'closed', 63, 'demo@openuvoice.com', 'הועבר לצוות הקורס, אישרו שיוסיפו תצפית בסמסטר הבא.', 'הצעה: לארגן תצפית כוכבים לסטודנטים של צפונות היקום. כבר היו כמה ששאלו על זה בקבוצה.'),
    (20522, 'exams', 'closed', 77, 'demo@openuvoice.com', 'נבדק מול המדור לבחינות, התנגשות נפתרה.', 'מבחן תורת הקוואנטים א'' נקבע באותו יום כמו מבחן חדו״א ב''. הרבה סטודנטים לוקחים את שניהם.')
  ) as v (course, type, status, days, handled_by, note, content)
  -- Only courses this database knows.
  join courses c on c.course_number = v.course;

-- At most one announcement is pinned, so the demo one is pinned only when none is.
insert into announcements (title, body, published_at, pinned, author_email, created_at)
select v.title, v.body,
       case when v.state = 'draft' then null else now() - v.days * interval '1 day' end,
       v.state = 'pinned' and not exists (select 1 from announcements where pinned),
       'demo@openuvoice.com',
       now() - v.days * interval '1 day'
  from (values
    ('pinned', 2, 'ברוכים הבאים ל־OpenUVoice', 'האתר נבנה על ידי סטודנטים, בשביל סטודנטים לפיזיקה באוניברסיטה הפתוחה.

כאן אפשר לקרוא ולכתוב ביקורות על כל קורס, לדרג אותו, לשאול שאלות בצ''אט הכללי, ולפנות לוועד באופן אנונימי.

האתר אינו אתר רשמי של האוניברסיטה הפתוחה.'),
    ('published', 6, 'ערב היכרות לסטודנטים חדשים', 'ביום שלישי הקרוב בשעה 20:30 ייערך בזום ערב היכרות לסטודנטים בשנה הראשונה. נדבר על בחירת קורסים, איך להתמודד עם העומס, ועל מה שהיינו רוצים לדעת כשהתחלנו.

הקישור יישלח ביום האירוע.'),
    ('published', 19, 'עדכון: ימי השלמה במעבדות', 'בעקבות פניות רבות של סטודנטים במילואים, צוות המעבדות הוסיף ימי השלמה בסוף הסמסטר. פרטים ותאריכים באתר הקורס של כל מעבדה.'),
    ('draft', 0, 'סקר שביעות רצון מהקורסים', 'טיוטה: בקרוב נפתח סקר קצר על הקורסים של הסמסטר. התשובות אנונימיות, והתוצאות יוצגו כאן.')
  ) as v (state, days, title, body);

commit;
\echo Admin demo data loaded.
